 4	/**
 5	  * A simple model of a seaweed.
 6	 * 
 7	 * Seaweed age, consume oxygen during the night and produce oxygen during the daytime, propogate, 
 8	 * and may die of that or of weather.
 9	 *
10	 * @version 2022/03/02
11	 */
12	public class Seaweed extends Creature
13	{
14	   
15	    // The age at which a seaweed becomes mature and could be edible.
16	    private static final int MATURE_AGE = 20;
17	    // The age to which a shrimp can live.
18	    private static final int MAX_AGE = 40;
19	    // The maximum number of births.
20	    private static final int MAX_PROPAGATE_SIZE = 1;
21	    // A shared random number generator to control breeding.
22	    private static final Random rand = Randomizer.getRandom();
23	    // The amount of oxygen a plant need to survive in night.
24	    private static final double PLANT_OXYGEN_REQUIRED = 0.00000002;
25	    // The amount of oxygen a plant generated during day time.
26	    private static final double OXYGEN_GENERATED = 0.0000005;
27	    
28	     
29	    // Individual characteristics (instance fields).
30	    
31	    // The seaweed's age.
32	    private int age;
33	    
34	    /**
35	     * Constructor for objects of class Seaweed
36	     */
37	    public Seaweed(boolean randomAge, Field field, Location location)
38	    {
39	        super(field, location);
40	        age = 0;
41	        if(randomAge) {
42	            age = rand.nextInt(MAX_AGE);
43	        }  
44	    }
45	
46	   /**
47	     * This is what the seawead does most of the time - stay motionlessly under the water
48	     * @param newSeaweeds A list to return newly born shrimps.
49	     * @param atDayTime true if current step is daytime false otherwise.
50	     * @param oxygenLevel The inital level of dissolved oxygen in the water.
51	     * @param disease The disease may happened during simulation.  
52	     * @param step current step.
53	     * 
54	     * @return the oxygen level the species produced or consumed after action.
55	     */
56	    public double act(List<Creature> newSeaweeds, boolean atDayTime, double oxygenLevel, Disease disease,  int step)
57	    {
58	        incrementAge();
59	        if(oxygenLevel < PLANT_OXYGEN_REQUIRED){
60	            setDead();
61	            return 0;
62	        }    
63	        
64	       
65	        if(isAlive()){
66	            if(age >= MATURE_AGE)
67	                giveBirth(newSeaweeds);            
68	            }
69	        
70	        
71	        if(atDayTime)
72	            return OXYGEN_GENERATED;
73	        else
74	            return -PLANT_OXYGEN_REQUIRED;
75	        }
76	    
77	    /**
78	     * Increase the age.
79	     * This could result in the shrimp's death.
80	     */
81	    private void incrementAge()
82	    {
83	        age++;
84	        if(age > MAX_AGE) {
85	            setDead();
86	        }
87	    }
88	    
89	    /**
90	     * Check whether or not this shrimp is to give birth at this step.
