92	     * @param newSeaweeds A list to return newly propagated seaweed.
93	     */
94	    private void giveBirth(List<Creature> newSeaweeds)
95	    {
96	        createAdjacentCreatures(newSeaweeds, MAX_PROPAGATE_SIZE,
97	            (field, location) -> new Seaweed(false, field, location));
98	    }
99	}

